// One deterministic fictional history per instrument. Prices and timestamps are shared
// by every period, including HOT WATCH; the reference is a closed historical session.
window.ESCAPE_DEMO_HISTORY=(()=>{
 const end=Date.parse('2026-11-06T21:00:00Z'), start=end-365*86400000, cache=new Map();
 const zones={ASML:'Europe/Amsterdam',NOVOB:'Europe/Copenhagen',GMAB:'Europe/Copenhagen'}, calendars=new Map();
 const crypto=new Set(['BTC','PEPE']);
 // Calendars cover this demo's fixed 2025-11-06 to 2026-11-06 window only.
 // Sources: Nasdaq US and Copenhagen calendars, Euronext Amsterdam calendar.
 const closures={
  'America/New_York':new Set(['2025-11-27','2025-12-25','2026-01-01','2026-01-19','2026-02-16','2026-04-03','2026-05-25','2026-06-19','2026-07-03','2026-09-07']),
  'Europe/Copenhagen':new Set(['2025-12-24','2025-12-25','2025-12-26','2025-12-31','2026-01-01','2026-04-02','2026-04-03','2026-04-06','2026-05-14','2026-05-15','2026-05-25','2026-06-05']),
  'Europe/Amsterdam':new Set(['2025-12-25','2025-12-26','2026-01-01','2026-04-03','2026-04-06','2026-05-01'])
 };
 const earlyClose={'America/New_York':{'2025-11-28':780,'2025-12-24':780},'Europe/Amsterdam':{'2025-12-24':845,'2025-12-31':845}};
 const money=n=>({amount:Number(n).toFixed(2),currency:'DKK'});
 function history(p){
  const key=p.asset_id;if(cache.has(key))return cache.get(key);
  const isCrypto=crypto.has(p.ticker),zone=zones[p.ticker]||'America/New_York';
  const local=new Intl.DateTimeFormat('en-US',{timeZone:zone,year:'numeric',month:'2-digit',day:'2-digit',weekday:'short',hour:'2-digit',minute:'2-digit',hourCycle:'h23'});
  let seed=2166136261;for(const c of key)seed=Math.imul(seed^c.charCodeAt(0),16777619)>>>0;
  const random=()=>{seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed/4294967296};
  const calendarKey=isCrypto?'crypto':zone;
  if(!calendars.has(calendarKey)){
   const timestamps=[],step=(isCrypto?10:3)*60000;
   for(let t=start;t<=end;t+=step){
    if(!isCrypto){const parts=local.formatToParts(new Date(t)),get=k=>parts.find(x=>x.type===k)?.value,weekday=get('weekday'),day=get('year')+'-'+get('month')+'-'+get('day'),minute=Number(get('hour'))*60+Number(get('minute')),close=earlyClose[zone]?.[day]??(zones[p.ticker]?1020:960);
     if(weekday==='Sat'||weekday==='Sun'||closures[zone].has(day)||minute<(zones[p.ticker]?540:570)||minute>close)continue;
    }
    timestamps.push(t);
   }
   calendars.set(calendarKey,timestamps);
  }
  let level=0,momentum=0,rows=[];
  for(const t of calendars.get(calendarKey)){
   const drift=(random()-.5)*.0014;momentum=momentum*.88+drift*.12;
   const signalBias=t>end-6*3600000&&t>calendars.get(calendarKey).at(-1)-15*60000?(p.ticker==='NOVOB'?.0008:p.ticker==='TSLA'?-.0008:0):0;
   level+=drift+momentum+signalBias;
   rows.push({epoch:t/1000,timestamp:new Date(t).toISOString(),log:level});
  }
  const base=Number(p.price.amount),last=rows[rows.length-1].log;
  rows=rows.map(r=>({epoch:r.epoch,timestamp:r.timestamp,date:r.timestamp.slice(0,10),price:(base*Math.exp(r.log-last)).toFixed(12)}));
  rows[rows.length-1].price=Number(p.price.amount).toFixed(12);cache.set(key,rows);return rows;
 }
 function period(p,which){const all=history(p),last=all[all.length-1].epoch,days=which==='ONE_MONTH'?30:which==='ONE_YEAR'?365:7,subset=all.filter(x=>x.epoch>last-days*86400);
  // Keep the last session dense for the day chart and sample older observations.
  const lastDay=last-86400,old=subset.filter(x=>x.epoch<=lastDay),recent=subset.filter(x=>x.epoch>lastDay);
  const target=which==='ONE_YEAR'?330:which==='ONE_MONTH'?220:250, budget=Math.max(1,target-recent.length),stride=Math.max(1,Math.ceil(old.length/budget));
  return old.filter((_,i)=>i%stride===0).concat(recent);
 }
 const positions=window.ESCAPE_DEMO_DATA.state.dashboard.positions,d=window.ESCAPE_DEMO_DATA.state.dashboard;
 const source=positions.find(p=>p.ticker==='BTC');
 function at(rows,epoch){let lo=0,hi=rows.length;while(lo<hi){const mid=(lo+hi)>>1;if(rows[mid].epoch<=epoch)lo=mid+1;else hi=mid}return rows[Math.max(0,lo-1)]}
 const histories=positions.map(history), daySource=period(source,'ONE_WEEK').filter(x=>x.epoch>history(source).at(-1).epoch-86400),dayStart=daySource[0].epoch;
 positions.forEach((p,i)=>{const last=histories[i].at(-1),first=at(histories[i],dayStart),change=(Number(last.price)-Number(first.price))*Number(p.quantity);p.price_time=last.timestamp;p.daily={...p.daily,amount:change.toFixed(2),percent:String((Number(last.price)/Number(first.price)-1)*100),to:p.price_time};if(p.raw)p.raw.price_time=p.price_time;});
 d.daily_result=money(positions.reduce((n,p)=>n+Number(p.daily.amount),0));
 for(const [name,which] of [['day','ONE_WEEK'],['week','ONE_WEEK'],['month','ONE_MONTH'],['year','ONE_YEAR']]){
  const timeline=name==='day'?daySource:period(source,which);
  d.portfolio_value_history.periods[name]=timeline.map(point=>{const value=positions.reduce((sum,p,i)=>sum+Number((Number(at(histories[i],point.epoch).price)*Number(p.quantity)).toFixed(2)),0);return {at:point.timestamp,amount:value.toFixed(2),currency:'DKK',reported_result:(value-50000).toFixed(2)}});
 }

 return {history,period};
})();
